            "required": ["customer_id", "zip_code"],
        },
    },
    {
        "name": "list_orders",
        "description": "List a customer's orders, newest delivery first.",
        "parameters": {
            "type": "object",
            "properties": {"customer_id": {"type": "string"}},
            "required": ["customer_id"],
        },
    },
    {
        "name": "get_order",
        "description": "Get one order's status, total, delivery date and address.",
        "parameters": {
            "type": "object",
            "properties": {"order_id": {"type": "string"}},
            "required": ["order_id"],
        },
    },
    {
        "name": "refund_order",
        "description": "Refund an order in full. Check the policy first.",
        "parameters": {
